import sys

def main():
    data = sys.stdin.read().split()
    s, k = data[0], int(data[1])
    st = []
    for ch in s:
        if st and st[-1][0] == ch:
            st[-1][1] += 1
        elif st and st[-1][1] >= k:
            st.pop()
            if st and st[-1][0] == ch:
                st[-1][1] += 1
            else:
                st.append([ch, 1])
        else:
            st.append([ch, 1])
    if st and st[-1][1] >= k:
        st.pop()
    res = ''.join(c * m for c, m in st)
    print(res if res else 'EMPTY')

